export function arrangementAt(bar) {
  const b=bar%32;
  if(b<4)return {lead:b>=2,drums:b>=1,bass:true,pads:true,arp:true,energy:.68,section:'intro'};
  if(b<12)return {lead:true,drums:true,bass:true,pads:true,arp:false,energy:.88,section:'verse'};
  if(b<16)return {lead:true,drums:true,bass:true,pads:true,arp:true,energy:.95,section:'build'};
  if(b<24)return {lead:true,drums:true,bass:true,pads:true,arp:true,energy:1,section:'chorus'};
  if(b<28)return {lead:b%2===0,drums:false,bass:b%2===0,pads:true,arp:true,energy:.6,section:'bridge'};
  return {lead:true,drums:true,bass:true,pads:true,arp:true,energy:.95,section:'finale'};
}
